<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{PakistanErpRepository,SettingsRepository};use App\Services\WhatsAppService;use App\Support\Flash;
final class WhatsAppController extends AdminPageController{private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function r():PakistanErpRepository{return new PakistanErpRepository($this->app->database());}public function index(Request$q):Response{return$this->view('communication/whatsapp',['pageTitle'=>'WhatsApp Communication','activeMenu'=>'whatsapp','activeSubmenu'=>'whatsapp','institute'=>(new SettingsRepository($this->app->database()))->institute(),'templates'=>$this->r()->whatsappTemplates($this->i())]);}public function template(Request$q):Response{try{$this->r()->saveWhatsappTemplate($this->i(),(string)$q->input('event_key'),(string)$q->input('name'),(string)$q->input('body'));Flash::add('success','WhatsApp template saved.');}catch(\Throwable$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/whatsapp'));}public function open(Request$q):Response{$s=new WhatsAppService();try{$phone=$s->normalize((string)$q->input('phone'));$message=$s->render((string)$q->input('message'),[]);$this->r()->logWhatsapp($this->i(),null,'manual',null,$phone,$message,(int)user()['id']);return Response::redirect($s->clickUrl($phone,$message));}catch(\Throwable$e){Flash::add('error',$e->getMessage());return Response::redirect(url('/admin/whatsapp'));}}}
